using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Text.RegularExpressions;
namespace Synkoz {
 public sealed class PatchParamR2 {public int Kind,Number,Bits;public string Name,Short;}
 public sealed class PatchR2 {public string Name,Source;public List<PatchParamR2> Parameters=new List<PatchParamR2>();
  static bool NameOk(string s,int min,int max){return s.Length>=min&&s.Length<=max&&Regex.IsMatch(s,"^[A-Za-z0-9 _-]+$");}
  public static PatchR2 Read(string path){string raw=File.ReadAllText(path);if(!raw.EndsWith("\n")||raw.Length>1000000)throw new Exception("Patch incomplet.");var lines=raw.Replace("\r","").Split('\n');var h=lines[0].Split(',');int version;if(h.Length!=3||h[0]!="UKITEM"||!int.TryParse(h[1],out version)||version<1||version>12||h[2]!="1"||lines.Length<4||!lines[1].StartsWith("NAME,")||lines[lines.Length-2]!="END"||lines.Last()!="")throw new Exception("Format UKH incompatible.");var p=new PatchR2{Name=lines[1].Substring(5),Source=Path.GetFullPath(path)};if(!NameOk(p.Name,1,48))throw new Exception("Nom de patch invalide.");foreach(string line in lines.Skip(2).Take(lines.Length-4)){var f=line.Split(',');int kind,number,bits;if(f.Length!=6||f[0]!="P"||!int.TryParse(f[1],out kind)||!int.TryParse(f[2],out number)||!int.TryParse(f[3],out bits)||kind<0||kind>1||number<0||number>16383||(bits!=7&&bits!=14)||(kind==0&&(number>127||bits!=7))||!NameOk(f[4],1,6)||!NameOk(f[5],3,3))throw new Exception("Paramètre UKH invalide : "+line);p.Parameters.Add(new PatchParamR2{Kind=kind,Number=number,Bits=bits,Name=f[4],Short=f[5]});}return p;}
  public override string ToString(){return Name;}
  public const string Prompt="À partir de l’implémentation MIDI jointe, produire un fichier texte ASCII .UKH compatible Urban Kaoz, terminé par un saut de ligne. Ne rien inventer : signaler séparément les informations absentes et citer les pages utilisées. Structure : UKITEM,12,1 puis NAME,nom (1 à 48 caractères), puis une ligne P,type,numéro,bits,nom,abréviation par paramètre, puis END. type=0 pour CC (numéro 0..127, bits=7), type=1 pour NRPN (numéro 0..16383, bits=7 ou 14 selon documentation). Nom paramètre : 1..6 caractères ; abréviation : exactement 3. Noms : lettres ASCII, chiffres, espaces, tiret ou underscore uniquement. Exemple :\nUKITEM,12,1\nNAME,Mon instrument\nP,0,74,7,Cutoff,CUT\nEND\nNe pas confondre NRPN et CC, ni adresse du paramètre et valeur MIDI.";
 }
 public static class PatchLabelsR2 {
  public static string Label(Montage m,Effect936 e,int cc){var channels=e.ByTrack15?m.CC.Where(c=>EventsR9.Channel(e,c.Channel,c.Track940)).Select(c=>c.Channel).Distinct().ToArray():Enumerable.Range(0,16).Where(c=>(e.Channel==0&&e.ChannelsR9==0)||EventsR9.Channel(e,c)).ToArray();var names=new List<string>();foreach(int ch in channels){var sources=m.CC.Where(c=>c.Channel==ch&&c.Number==cc&&c.Track940>=0&&(!e.ByTrack15||EventsR9.Channel(e,c.Channel,c.Track940))).Select(c=>c.Track940).Distinct().ToArray();var sets=m.MidiPatchesR2.Where(x=>x.SourceTrack>=0?sources.Contains(x.SourceTrack):!e.ByTrack15&&x.Channel==ch+1).SelectMany(x=>x.Patches).OrderBy(x=>x.Name,StringComparer.OrdinalIgnoreCase).ThenBy(x=>x.Source,StringComparer.OrdinalIgnoreCase);var q=sets.SelectMany(x=>x.Parameters).FirstOrDefault(x=>x.Kind==0&&x.Bits==7&&x.Number==cc);if(q!=null)names.Add(q.Name);}return names.Count==0?"CC "+cc:string.Join(" / ",names.Distinct())+" (CC "+cc+")";}
 }
 public sealed class MidiPatchAssignmentR2 {public int SourceTrack=-1,Channel;public List<PatchR2> Patches=new List<PatchR2>();}
 public sealed class GeneralSettingsR2:Form {
  public GeneralSettingsR2(){Text="Paramètres généraux";UiR2.Fit(this,760,510);var tabs=new TabControl{Dock=DockStyle.Fill};var page=new TabPage("Dossiers par défaut");var rows=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};page.Controls.Add(rows);tabs.TabPages.Add(page);Controls.Add(tabs);var prefs=Preferences936.Load();var fields=new Dictionary<string,TextBox>();string[] keys={"prise","config","montage","project","export","animation","fx","audio","fonts","patch"};string[] labels={"Prises","Configurations","Ouverture des montages","Projets","Exports","Animations","Effets / chaînes","Presets audio","Polices personnelles","Patches MIDI"};for(int i=0;i<keys.Length;i++){string key=keys[i];var row=new FlowLayoutPanel{Width=690,Height=55};row.Controls.Add(new Label{Text=labels[i],Width=175});var box=new TextBox{Width=390,Text=key=="prise"?prefs.DefaultTakeFolder:key=="config"?prefs.LastConfigFolder:FoldersR2.Get(key)};fields[key]=box;row.Controls.Add(box);var browse=new Button{Text="Choisir…",Width=90};browse.Click+=delegate{using(var d=new FolderDialog08{SelectedPath=box.Text})if(d.ShowDialog(this)==DialogResult.OK)box.Text=d.SelectedPath;};row.Controls.Add(browse);rows.Controls.Add(row);}var save=new Button{Text="Enregistrer",Dock=DockStyle.Bottom,Height=34};save.Click+=delegate{try{foreach(var item in fields){if(!Path.IsPathRooted(item.Value.Text))throw new Exception("Choisir un chemin absolu.");Directory.CreateDirectory(item.Value.Text);}}catch(Exception ex){Synkoz.ErrorR8.Show(this,ex.Message);return;}foreach(var item in fields){if(item.Key=="prise"||item.Key=="config")continue;FoldersR2.Set(item.Key,item.Value.Text);}var p=Preferences936.Load();p.DefaultTakeFolder=fields["prise"].Text;p.LastConfigFolder=fields["config"].Text;p.Save();Preferences936.NotifyR2();DialogResult=DialogResult.OK;};Controls.Add(save);}
 }
 public sealed class PatchSettingsR2:Form {
  public PatchSettingsR2(Montage m){Text="Paramètres du projet — Patches";UiR2.Fit(this,800,540);var assignments=UiR2.Copy(m.MidiPatchesR2);var channels=new ComboBox{Dock=DockStyle.Top,DropDownStyle=ComboBoxStyle.DropDownList};for(int i=1;i<=16;i++)channels.Items.Add("Piste MIDI "+i);for(int i=1;i<=16;i++)channels.Items.Add("Canal MIDI "+i+" (source externe)");var list=new ListBox{Dock=DockStyle.Fill};Action refresh=()=>{list.Items.Clear();var a=assignments.FirstOrDefault(x=>channels.SelectedIndex<16?x.SourceTrack==channels.SelectedIndex:x.SourceTrack<0&&x.Channel==channels.SelectedIndex-15);if(a!=null)list.Items.AddRange(a.Patches.Cast<object>().ToArray());};channels.SelectedIndexChanged+=delegate{refresh();};channels.SelectedIndex=0;Controls.Add(list);Controls.Add(channels);var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=75};var add=new Button{Text="Ajouter patch…",AutoSize=true};add.Click+=delegate{using(var d=new OpenFileDialog{AutoUpgradeEnabled=true,Multiselect=true,Filter="Patches Urban Kaoz|*.ukh",InitialDirectory=FoldersR2.Get("patch")})if(d.ShowDialog(this)==DialogResult.OK)try{var loaded=d.FileNames.Select(PatchR2.Read).ToArray();var a=assignments.FirstOrDefault(x=>channels.SelectedIndex<16?x.SourceTrack==channels.SelectedIndex:x.SourceTrack<0&&x.Channel==channels.SelectedIndex-15);if(a==null){a=new MidiPatchAssignmentR2{SourceTrack=channels.SelectedIndex<16?channels.SelectedIndex:-1,Channel=channels.SelectedIndex<16?0:channels.SelectedIndex-15};assignments.Add(a);}a.Patches.AddRange(loaded);a.Patches=a.Patches.OrderBy(x=>x.Name,StringComparer.OrdinalIgnoreCase).ToList();FoldersR2.Set("patch",Path.GetDirectoryName(d.FileName));refresh();}catch(Exception ex){Synkoz.ErrorR8.Show(this,ex.Message);}};actions.Controls.Add(add);var remove=new Button{Text="Retirer",AutoSize=true};remove.Click+=delegate{var p=list.SelectedItem as PatchR2;if(p!=null){assignments.First(x=>channels.SelectedIndex<16?x.SourceTrack==channels.SelectedIndex:x.SourceTrack<0&&x.Channel==channels.SelectedIndex-15).Patches.Remove(p);refresh();}};actions.Controls.Add(remove);var prompt=new Button{Text="Prompt de création…",AutoSize=true};prompt.Click+=delegate{using(var f=new Form{Text="Créer un patch depuis une implémentation MIDI",Width=740,Height=480}){f.Controls.Add(new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,Text=PatchR2.Prompt});var copy=new Button{Text="Copier le prompt",Dock=DockStyle.Bottom};copy.Click+=delegate{Clipboard.SetText(PatchR2.Prompt);};f.Controls.Add(copy);f.ShowDialog(this);}};actions.Controls.Add(prompt);var ok=new Button{Text="Valider",AutoSize=true};ok.Click+=delegate{m.MidiPatchesR2=assignments;m.Save();DialogResult=DialogResult.OK;};actions.Controls.Add(ok);actions.Controls.Add(new Label{Text="Plusieurs patches : priorité alphabétique. Libellés CC ; NRPN conservés séparément.",AutoSize=true});Controls.Add(actions);}
 }
}
